protected void FinishEdit()
{
    if (!m_IsEditing)
        return;

    Lightmapping.PopGIWorkflowMode();

    OnToolDisengaged();

    var selection = MeshSelection.topInternal.ToArray();

    foreach (var mesh in selection)
    {
        mesh.ToMesh();
        mesh.Refresh();
        mesh.Optimize();
    }

    ProBuilderEditor.Refresh(false);

    if (afterMeshModification != null)
        afterMeshModification(selection);

    m_IsEditing = false;
}

public override bool enabled
{
    get
    {
        switch (ProBuilderEditor.selectMode)
        {
            case SelectMode.Edge:
                return EditorToolbarLoader.GetInstance<ExtrudeEdges>().enabled;
            case SelectMode.Face:
                return EditorToolbarLoader.GetInstance<ExtrudeFaces>().enabled;
            default:
                return false;
        }
    }
}

public override bool hidden
{
    get { return true; }
}

protected override ActionResult PerformActionImplementation()
{
    switch (ProBuilderEditor.selectMode)
    {
        case SelectMode.Edge:
            return EditorToolbarLoader.GetInstance<ExtrudeEdges>().PerformAction();
        case SelectMode.Face:
            return EditorToolbarLoader.GetInstance<ExtrudeFaces>().PerformAction();

        default:
            return ActionResult.NoSelection;
    }
}

